const CACHE='fieldfare-v1.0.1';
const SHELL=['./','./index.html','./style.css','./app.js','./data.js','./logic.js','./locations.json','./manifest.webmanifest','./assets/lucide.min.js','./assets/zxing.min.js','./assets/pasture.jpg','./assets/favicon.svg','./assets/icon-180.png','./assets/icon-192.png','./assets/icon-512.png'];
const urls=SHELL.map(p=>new URL(p,self.registration.scope).href);
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);for(const url of urls){const response=await fetch(url,{cache:'reload',credentials:'same-origin'});if(!response.ok||response.redirected)throw new Error('App asset not available');await cache.put(url,response)} })()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('fieldfare-')&&key!==CACHE)await caches.delete(key);await self.clients.claim()})()));
self.addEventListener('message',event=>{if(event.data?.type==='SKIP_WAITING')self.skipWaiting();if(event.data?.type==='CACHE_STATUS')event.waitUntil((async()=>{const cache=await caches.open(CACHE);const keys=await cache.keys();event.ports[0]?.postMessage({ready:urls.every(u=>keys.some(k=>k.url===u)),version:CACHE})})())});
self.addEventListener('fetch',event=>{const request=event.request;if(request.method!=='GET'||new URL(request.url).origin!==self.location.origin)return;if(request.mode==='navigate'){event.respondWith((async()=>{try{return await fetch(request)}catch{return (await caches.match(new URL('./index.html',self.registration.scope).href))||Response.error()}})());return}if(urls.includes(request.url))event.respondWith(caches.match(request).then(cached=>cached||fetch(request)))});
